head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "JLDBNF60200";
scwin.result = null;
scwin.dmenus = undefined;
scwin.initSriBndAppl = null;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "__rb0", fn: function () { return String(String((dma_pageContext.get("isurNm") ?? ""))); } },
        { childId: "__rb1", fn: function () { return String(String((dma_pageContext.get("isurCd") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name initPageIndex
 * @description init Page Index 처리
 * @returns {void}
 * @hidden N
 */
scwin.initPageIndex = function () {
    $c.util.getComponent('dma_showSuplyFndUseRptListReq').set('pageIndex', "1");
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.dmenus ={
        "bmenu":8
        ,"mmenu":1
    }; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldbnf60200' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.initSriBndAppl = initSriBndAppl;
        scwin.init_rowCopy();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jldbnf60200.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name table_94_oncellclick
 * @description table_94 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.table_94_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try { if (columnId === 'file_cnt') { let __d = $c.util.getComponent('dlt_sriappl'); if (!__d) { return; } if (Number(__d.getCellData(rowIndex, "file_cnt")) > 0) { await scwin.showEtcFileList(String(__d.getCellData(rowIndex, "std_cd")), String(__d.getCellData(rowIndex, "appl_isu_seq"))); } return; } if (columnId === 'stat') { __d = $c.util.getComponent('dlt_sriappl'); if (!__d) { return; } if (String(__d.getCellData(rowIndex, "stat")) === "반송") { await scwin.OpenRetViewSri(String(__d.getCellData(rowIndex, "std_cd")), String(__d.getCellData(rowIndex, "appl_isu_seq"))); } return; }
    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60200.table_94_oncellclick' }); }
};

/**
 * @method
 * @name ipt_searchWord_onkeypress
 * @description ipt_searchWord onkeypress 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onkeypress = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.str.replaceAll(selfVar);

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60200.ipt_searchWord_onkeypress' }); }
};

/**
 * @method
 * @name ipt_searchWord_onpaste
 * @description ipt_searchWord onpaste 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.ipt_searchWord_onpaste = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf60200.ipt_searchWord_onpaste' }); }
};

/**
 * @method
 * @name btn_showSuplyFndUseRptView_onclick
 * @description btn_showSuplyFndUseRptView 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_showSuplyFndUseRptView_onclick = async function(e){
    try {
        await scwin.showSuplyFndUseRptView()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60200.btn_showSuplyFndUseRptView_onclick' }); }
};

/**
 * @method
 * @name btn_showSuplyFndUseRptList_onclick
 * @description btn_showSuplyFndUseRptList 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_showSuplyFndUseRptList_onclick = async function(e){
    try {
        await scwin.showSuplyFndUseRptList()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60200.btn_showSuplyFndUseRptList_onclick' }); }
};

/**
 * @method
 * @name grd_result_oncellclick
 * @description grd_result 셀 클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.grd_result_oncellclick = async function (rowIndex, columnIndex, columnId) {
    try {
        const dl = $c.util.getComponent('dlt_result');
        if (!dl) { /* TODO Stage2: [sdd] 행 동작 대상 목록 없음: dlt_result */ return; }
        const r = dl.getRowJSON ? dl.getRowJSON(rowIndex) : null;
        if (!r) { return; } /* 수동 전환 필요: focus_tr (인자 미해석) · fn_initSriBndAppl(${status.count-1}, ${fn:length(result)}); (EL 미해석) */
        if (columnId === "check") { /* TODO Stage2: [sdd] 미실현 행 동작: fn_initSriBndAppl (as-is 인자를 못 옮겼습니다) */ await $c.win.alert('이 행 동작을 아직 정하지 못했습니다(전환 미완) — fn_initSriBndAppl'); return; }
    } catch (e) {
        await $c.exception.handleError(e, { notify: 'none', context: 'grd_result.oncellclick' });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_showSuplyFndUseRptList
 * @description show Suply Fnd Use Rpt List 서버 호출
 * @param {*} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_showSuplyFndUseRptList = async function (action) {
    const sbmOptions = {
        id: "tx_fn_showSuplyFndUseRptList",
        method: "post",
        action: action ?? "/sri/sribnd.do",
        ref: "dma_showSuplyFndUseRptListReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fn_initSriBndAppl
 * @description init Sri Bnd Appl 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_initSriBndAppl = async function () {
    const sbmOptions = {
        id: "tx_fn_initSriBndAppl",
        method: "post",
        action: "/sri/sribnd.do",
        ref: "dma_initSriBndApplReq",
        target: "dlt_sriappl=sriappl",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
