    const sbmOptions = {
        id: "tx_fn_showSuplyFndUseRptView",
        method: "post",
        action: action ?? "/sri/sribnd.do?std_cd=",
        ref: "dma_showSuplyFndUseRptViewReq",
        target: "dlt_result=body.content",
        isProcessMsg: false
