    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_OpenRetViewSri
 * @description Open Ret View Sri 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_OpenRetViewSri = async function () {
    const sbmOptions = {
        id: "tx_OpenRetViewSri",
        method: "post",
        action: "/sri/sribnd.do",
        ref: "dma_OpenRetViewSriReq",
