    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_check_procs_yn
 * @description check procs yn 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_check_procs_yn = async function () {
    const sbmOptions = {
        id: "tx_check_procs_yn",
        method: "post",
        action: "/sri/sribnd.do",
        ref: "dma_checkProcsYnReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name table_94_fmt_appl_dd
 * @description table 94 fmt appl dd 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.table_94_fmt_appl_dd = function (data, formattedData, rowIndex, columnIndex) { const d = $c.util.getComponent('dlt_sriappl'); const b = d ? d.getCellData(rowIndex, "appl_tm") : ''; return ((data === undefined || data === null) ? '' : String(data)) + '<br>' + ((b === undefined || b === null) ? '' : String(b)); };

/**
 * @method
 * @name table_94_fmt_file_cnt
 * @description table 94 fmt file cnt 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.table_94_fmt_file_cnt = function (data, formattedData, rowIndex, columnIndex) { if (Number(data) > 0) { return "<a href=\"javascript:void(0)\">열기</a>"; } return (data === undefined || data === null) ? '' : String(data); };

/**
 * @method
 * @name table_94_fmt_stat
 * @description table 94 fmt stat 처리
 * @param {*} data 데이터
 * @param {*} formattedData 포맷된 값
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @returns {void}
 * @hidden N
 */
scwin.table_94_fmt_stat = function (data, formattedData, rowIndex, columnIndex) { if (String(data) === "반송") { return '<a href="javascript:void(0)"><strong>' + String(data) + '</strong></a>'; } return (data === undefined || data === null) ? '' : String(data); };

/**
 * @method
 * @name __on_enter_1_ipt_searchword
 * @description on enter 1 ipt searchword 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.__on_enter_1_ipt_searchword = async function(e){
    try {
        const ev = e;
        if(($c.util.getKeyCode(ev))===13){ await scwin.showSuplyFndUseRptList() }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldbnf60200.__on_enter_1_ipt_searchWord' }); }
};

/**
 * @method
 * @name showSuplyFndUseRptList
 * @description show Suply Fnd Use Rpt List 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showSuplyFndUseRptList = async function () {
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("method", "showSuplyFndUseRptList");
    await scwin.tx_fn_showSuplyFndUseRptList('/sri/sribnd.do');
};

async function initSriBndAppl(rowIdx, rownum) {
    if (rownum === 1) {
        $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndStdCd", $c.util.getComponent("dma_showSuplyFndUseRptListReq").get("stdCd"));
    } else {
        if (rownum > 1) {
            $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndStdCd", $c.util.getComponent('dlt_result').getCellData(rowIdx, 'isuCd'));
        }
    }
    $.ajax({ type: "POST", async: false, url: "../ajax/sri_data.jsp", data: $("#SearchForm").serialize(), success: function(data) {
                scwin.result = (typeof data === "string" ? (typeof data === "string" ? JSON.parse(data) : data) : data);
                const rowPlus = $c.util.getComponent("tbl_appl");
                let tr;
                let th;
                let td;
                let $tblAppl;
                let $tr;
                let $td1, $td2, $td3, $td4, $td5, $td6, $td7, $td8, $td9, $td10;
                /* 표 비움 → setJSON 전체 교체가 대신(표 앵커) */
                $c.util.getComponent('dlt_sriappl').setJSON(scwin.result.sriappl); /* as-is 조립 루프 → 그리드 공급으로 대체(표 앵커 #tbl_appl): 행은 dlt_sriappl 가 싣고 열 동작은 그리드가 낸다 · 빈 갈래까지 함께(그리드 빈 표시가 「데이터가 없습니다」를 대신한다) */
            }, error: async function(request, status, error) {
                await $c.win.alert("현재 서버에서 사후보고 신청현황을 가져올 수 없습니다. 관리자에게 문의하세요.");
                return;
            }, complete: function() {

            } });
    await scwin.tx_fn_initSriBndAppl();

}

/**
 * @method
 * @name showSuplyFndUseRptView
 * @description show Suply Fnd Use Rpt View 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showSuplyFndUseRptView = async function () {
    await scwin.check_procs_yn();
    if ($c.util.getComponent("dma_showSuplyFndUseRptListReq").get("sndStdCd") === '') {
        await $c.win.alert('종목을 선택하세요.');
        return;
    } else {
        if ($c.util.getComponent("dma_showSuplyFndUseRptListReq").get("checkProcsCnt") > 0) {
            await $c.win.alert('처리중인 종목은 신청 할 수 없습니다.');
            return;
        } else {
            $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("method", 'showSuplyFndUseRptView');
            await scwin.tx_fn_showSuplyFndUseRptView('/sri/sribnd.do?std_cd=' + $c.util.getComponent("dma_showSuplyFndUseRptListReq").get("sndStdCd"));
        }
    }
};

/**
 * @method
 * @name focus_tr
 * @description focus tr 처리
 * @param {Object} obj 컴포넌트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.focus_tr = async function (obj) {
    const radio = document.getElementsByName("check");
    let i;
    const tabNum = obj.parentNode.children.length;
    for (i = 0; i < tabNum; i++) {
        obj.parentNode.children[i].className = '';
        radio[i].checked = false;
    }
    obj.className = 'on';
    radio[obj.rowIndex -1].checked = true;
    await initSriBndAppl(obj.rowIndex - 1, obj.parentNode.children.length);
};

/**
 * @method
 * @name showEtcFileList
 * @description show Etc File List 처리
 * @param {String} p_stdCd p_stdCd
 * @param {*} p_applSeq p_applSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.showEtcFileList = async function (p_stdCd, p_applSeq) {
    fm = (document.SearchForm || { elements: [] });
    const width = 800;
    const height = 500;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/sri/sribnd.do?ipt_method=showEtcFileList", unresolved: "nav:" + "/sri/sribnd.do?ipt_method=showEtcFileList" }; })();
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndStdCd", p_stdCd);
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndApplIsuSeq", p_applSeq);
    fm.action = '/sri/sribnd.do?method=showEtcFileList';

    return;
};

/**
 * @method
 * @name OpenRetViewSri
 * @description Open Ret View Sri 처리
 * @param {String} p_stdCd p_stdCd
 * @param {*} p_applSeq p_applSeq
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.OpenRetViewSri = async function (p_stdCd, p_applSeq) {
    fm = (document.SearchForm || { elements: [] });
    const width = 450;
    const height = 250;
    const mtWidth = document.body.clientWidth;
    const mtHeight = document.body.clientHeight;
    const scX = 0;
    const scY = 0;
    const popX = scX + (mtWidth - width) / 2;
    const popY = scY + (mtHeight - height) / 2;
    let _previewWindow;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    _previewWindow = (function(){ throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + "/sri/sribnd.do", unresolved: "nav:" + "/sri/sribnd.do" }; })();
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndStdCd", p_stdCd);
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("sndApplIsuSeq", p_applSeq);
    $c.util.getComponent("dma_showSuplyFndUseRptListReq").set("method", 'returnViewSri');
    fm.action = '/sri/sribnd.do';

};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 4개다(tx_fn_showSuplyFndUseRptList, tx_fn_initSriBndAppl, tx_fn_showSuplyFndUseRptView, tx_OpenRetViewSri) — 어느 것이 «열자마자» 인지 정할 근거가 없다

// 억제된 trigger 함수의 as-is 이름 별칭 (호출자 정합)

/**
 * @method
 * @name check_procs_yn_done
 * @description check procs yn done 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.check_procs_yn_done = function (data) {
    scwin.result = (typeof data === "string" ? JSON.parse(data) : data);
    $c.util.getComponent('ipt_checkProcsCnt').setValue(scwin.result.sendResult);
};

/**
 * @method
 * @name check_procs_yn
 * @description check procs yn 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.check_procs_yn = async function () {
    const r = await scwin.tx_check_procs_yn();
    try {
        scwin.check_procs_yn_done.call(window, JSON.stringify((r && r.responseJSON && (r.responseJSON.body != null ? r.responseJSON.body : r.responseJSON)) || {}));
    }
    catch (_se) {
        await $c.exception.handleError(_se, { notify: 'none', context: 'jldbnf60200.check_procs_yn' });
    }
    return r;
};

/**
 * @method
 * @name krxpage_pagenavigator_91_onclick
 * @description krxpage_pagenavigator_91 클릭 이벤트
 * @param {Number} index index
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.krxpage_pagenavigator_91_onclick = async function (index) {
    try {
        const pi = (index && typeof index === 'object') ? index.newSelectedIndex : index;
        $c.util.getComponent('dma_showSuplyFndUseRptListReq').set('pageIndex', pi);
        await scwin.showSuplyFndUseRptList();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "jldbnf60200.krxpage_pagenavigator_91_onclick" });
    }
};
